@js:
JSON.stringify(["东方玄幻","古典仙侠","现代修真","都市生活","都市超能","架空历史","虚拟网游","时空穿梭","末世进化","古代言情","穿越重生","浪漫言情","烽火情缘","玄幻仙侠","都市幻想","悬疑灵异"].map((title)=>({
    title: title,
    url: `/api/getCateDetail?cate2=${title}&query=${title}&page={{page}}`,
    style: {
        layout_flexGrow: 1,
        layout_flexBasisPercent: 0.25
    }
})));

