};

(()=>{
  let base='https://m.shucangxs.com';
  if(page==1){
    let url=base+'/search.html';
    let body='searchkey='+key;

    return base+java.put('surl',java.post(url,body,headers).header("Location"));
  } else {
    return base+java.get('surl');
  }
})()

